# Rule Condition rows (Priority/Protocol Selection/Recommendation Rule) use
# plain Data condition_field, not a Link -- frappe.rename_doc will not
# auto-update these, so remap explicitly.
CONDITION_FIELD_REMAP = {
    "ch_vit_temperature": "temperature",
    "ch_vit_respiratory_rate": "respiratoryRate",
    "anc_temperature": "temperature",
}


def _remap_rule_conditions():
    for old, new in CONDITION_FIELD_REMAP.items():
        rows = frappe.get_all("Rule Condition", filters={"condition_field": old},
                               fields=["name", "parent", "parenttype"])
        for r in rows:
            frappe.db.set_value("Rule Condition", r.name, "condition_field", new)
            print(f"  [rule-condition] {r.parenttype}/{r.parent}: {old} -> {new}")


def run():
    frappe.flags.in_import = True
    renamed, merged, skipped = 0, 0, 0

    for new_name, info in PLAN.items():
        members = info["members"]
        primary = info["primary"]

        existing_members = [m for m in members if frappe.db.exists("Clinical Question", m)]
        if not existing_members:
            skipped += 1
            continue

        if new_name not in [m for m in existing_members] and not frappe.db.exists("Clinical Question", new_name):
            if not frappe.db.exists("Clinical Question", primary):
                print(f"  [skip] {new_name}: primary {primary} missing")
                continue
            frappe.rename_doc("Clinical Question", primary, new_name, force=True)
            print(f"  [rename] {primary} -> {new_name}")
            renamed += 1

        for m in existing_members:
            if m == new_name or m == primary:
                continue
            if not frappe.db.exists("Clinical Question", m):
                continue
            frappe.rename_doc("Clinical Question", m, new_name, merge=True, force=True)
            print(f"  [merge] {m} -> {new_name}")
            merged += 1

        if info["programmes"]:
            doc = frappe.get_doc("Clinical Question", new_name)
            existing_progs = {row.programme for row in doc.programmes}
            changed = False
            for p in info["programmes"]:
                if p not in existing_progs:
                    doc.append("programmes", {"programme": p})
                    changed = True
            if changed:
                doc.save(ignore_permissions=True)
                print(f"  [programmes] {new_name}: {info['programmes']}")

    _remap_rule_conditions()

    frappe.db.commit()
    print(f"Done. renamed={renamed} merged={merged} skipped={skipped}")
    print("Total Clinical Question rows now:", frappe.db.count("Clinical Question"))


if __name__ == "__main__":
    run()
